package raider.dsl.lineage.proj

import zio.*
import zio.test.*

object LineageRendererSpec extends ZIOSpecDefault:

  private val header =
    "// Generated by Raider lineage projection (ADR-027). Do not edit — comparator detects edits.\n"

  private val dryRunStatement =
    "// ADR-031 dry-run description: executing this projection dispatches no model call, no\n" +
      "// tool call, no I/O — it only reports the recorded call-graph structure. Not a replay\n" +
      "// or rerun entrypoint.\n"

  private val imports =
    "import raider.core.Program\n" +
      "import raider.dsl.lineage.proj.NodeKind\n" +
      "import raider.dsl.lineage.proj.runtime.{LineageStep, StepReport}\n"

  private def prelude(obj: String): String =
    header + dryRunStatement + "\n" + imports + "\n" + "object " + obj + ":\n"

  private def viewOf(id: String, rs: Vector[NodeView]): LineageView =
    new LineageView:
      def runId: String = id
      def roots: Vector[NodeView] = rs

  // Tiny view: one ModelCall root with a ToolCall child, one Delegation root
  // with a nested Phase child (LIN2-C-01 golden source of truth). After
  // RAI-141 the render is an EXECUTABLE Program/Task composition over
  // LineageStep (ADR-031): atomic steps in a value-threaded flatMap chain, the
  // delegation as a named def building a sub-Program, and a `val program`
  // entry point.
  private val tinyView: LineageView =
    viewOf(
      "run-2026-10-10",
      Vector(
        NodeView(
          "m1",
          NodeKind.ModelCall("glm-5.3-flash", 1),
          None,
          Vector(
            NodeView(
              "t1",
              NodeKind.ToolCall("files.write", "Mutating"),
              Some("m1"),
              Vector.empty,
              Some("d-tool-1")
            )
          ),
          Some("d-model")
        ),
        NodeView(
          "d1",
          NodeKind.Delegation("worker"),
          None,
          Vector(
            NodeView(
              "p1",
              NodeKind.Phase("verify"),
              Some("d1"),
              Vector.empty,
              Some("d-phase")
            )
          ),
          Some("d-del")
        )
      )
    )

  private val golden: String =
    prelude("lineage_run_2026_10_10") +
      "  val delegation_worker: Program[Unit, Vector[StepReport]] =\n" +
      "    Program.fromFunction(\"delegation_worker\") { _ =>\n" +
      "      LineageStep.delegation(\"d1\", \"worker\", Some(\"d-del\"), Vector.empty, nesting = 1) // data: d-del\n" +
      "        .flatMap { n_d1 =>\n" +
      "          phase_verify(()) // data: d-phase\n" +
      "            .map { n_p1 =>\n" +
      "              n_d1 ++ n_p1\n" +
      "            }\n" +
      "        }\n" +
      "    }\n" +
      "\n" +
      "  val phase_verify: Program[Unit, Vector[StepReport]] =\n" +
      "    Program.fromFunction(\"phase_verify\") { _ =>\n" +
      "      LineageStep.phase(\"p1\", \"verify\", Some(\"d-phase\"), Vector.empty, nesting = 2) // data: d-phase\n" +
      "    }\n" +
      "\n" +
      "  val program: Program[Unit, Vector[StepReport]] =\n" +
      "    Program.fromFunction(\"lineage_run_2026_10_10\") { _ =>\n" +
      "      LineageStep.model(\"m1\", \"glm-5.3-flash\", 1, Some(\"d-model\"), Vector.empty, nesting = 0) // data: d-model\n" +
      "        .flatMap { n_m1 =>\n" +
      "          LineageStep.tool(\"t1\", \"files.write\", \"Mutating\", Some(\"d-tool-1\"), Vector.empty, nesting = 0) // data: d-tool-1\n" +
      "            .flatMap { n_t1 =>\n" +
      "              delegation_worker(()) // data: d-del\n" +
      "                .map { n_d1 =>\n" +
      "                  n_m1 ++ n_t1 ++ n_d1\n" +
      "                }\n" +
      "            }\n" +
      "        }\n" +
      "    }\n"

  // Deep chain (L34): a phase whose subtree contains a nested Delegation. The
  // pre-RAI-141 indentation-region machinery (comment-only ancestors, closing
  // `()` markers) is gone: every def body is a real composition, so the old
  // comment-binding hazards cannot arise. The delegation def is
  // registered at object level in pre-order discovery order and called from
  // the phase body; its own node step lives INSIDE its body at nesting 2.
  private val deepChainView: LineageView =
    viewOf(
      "run-deep-001",
      Vector(
        NodeView(
          "n0",
          NodeKind.Phase("plan"),
          None,
          Vector(
            NodeView(
              "n1",
              NodeKind.ModelCall("mock-coder", 1),
              Some("n0"),
              Vector(
                NodeView(
                  "n2",
                  NodeKind.Delegation("worker"),
                  Some("n1"),
                  Vector(
                    NodeView(
                      "n3",
                      NodeKind.ModelCall("mock-coder", 1),
                      Some("n2"),
                      Vector(
                        NodeView(
                          "n4",
                          NodeKind.ToolCall("grep_search", "Idempotent"),
                          Some("n3"),
                          Vector.empty,
                          Some("d4")
                        )
                      ),
                      Some("d3")
                    )
                  ),
                  None
                )
              ),
              Some("d1")
            )
          ),
          None
        )
      )
    )

