  // RAI-141: IN-SCOPE dataflow threading. t1 depends on its sibling-chain
  // ancestor m1 in the same scope, so the generated inputs argument carries
  // the BOUND report value (`n_m1.head.id` — the pre-order vector of an
  // atomic step starts with the own node), not a string literal.
  private val threadedView: LineageView =
    viewOf(
      "run-threaded-001",
      Vector(
        NodeView(
          "m1",
          NodeKind.ModelCall("mock-coder", 1),
          None,
          Vector(
            NodeView(
              "t1",
              NodeKind.ToolCall("files.write", "Mutating"),
              Some("m1"),
              Vector.empty,
              Some("d1"),
              inputs = Vector("m1")
            )
          ),
          None
        )
      )
    )

  private val threadedGolden: String =
    prelude("lineage_run_threaded_001") +
      "  val program: Program[Unit, Vector[StepReport]] =\n" +
      "    Program.fromFunction(\"lineage_run_threaded_001\") { _ =>\n" +
      "      LineageStep.model(\"m1\", \"mock-coder\", 1, None, Vector.empty, nesting = 0)\n" +
      "        .flatMap { n_m1 =>\n" +
      "          LineageStep.tool(\"t1\", \"files.write\", \"Mutating\", Some(\"d1\"), Vector(n_m1.head.id), nesting = 0) // data: d1\n" +
      "            .map { n_t1 =>\n" +
