  // RAI-141: a recorded-failed node (graph outcome field, ADR-031 §2.4)
  // projects to LineageStep.failed — Task.fail typed, bounded payload-free
  // reason phrase (ADR-031 §2.5), dataRef key only.
  private def failedView(outcome: String): LineageView =
    viewOf(
      "run-failed-001",
      Vector(
        NodeView(
          "m1",
          NodeKind.ModelCall("mock-coder", 1),
          None,
          Vector(
            NodeView(
              "t1",
              NodeKind.ToolCall("edit_file", "Mutating"),
              Some("m1"),
              Vector.empty,
              Some("d1"),
              outcome = Some(outcome)
            )
          ),
          None
        )
      )
    )

  private def failedGolden(outcome: String): String =
    prelude("lineage_run_failed_001") +
      "  val program: Program[Unit, Vector[StepReport]] =\n" +
      "    Program.fromFunction(\"lineage_run_failed_001\") { _ =>\n" +
      "      LineageStep.model(\"m1\", \"mock-coder\", 1, None, Vector.empty, nesting = 0)\n" +
      "        .flatMap { n_m1 =>\n" +
      "          LineageStep.failed(\"t1\", NodeKind.ToolCall(\"edit_file\", \"Mutating\"), Some(\"d1\"), Vector.empty, nesting = 0, reason = \"recorded outcome: " + outcome + "\") // data: d1\n" +
      "            .map { n_t1 =>\n" +
      "              n_m1 ++ n_t1\n" +
      "            }\n" +
      "        }\n" +
      "    }\n"

  // A recorded failure on a named def's own node: the failed step lives
  // INSIDE the sub-Program body, so the short-circuit starts there and the
  // childless def still has one real statement (REN-01).
  private val failedDefView: LineageView =
    viewOf(
      "run-failed-def-001",
      Vector(
        NodeView(
          "d1",
          NodeKind.Delegation("worker"),
          None,
          Vector.empty,
          None,
          outcome = Some("Cancelled")
        )
