  private val failedDefGolden: String =
    prelude("lineage_run_failed_def_001") +
      "  val delegation_worker: Program[Unit, Vector[StepReport]] =\n" +
      "    Program.fromFunction(\"delegation_worker\") { _ =>\n" +
      "      LineageStep.failed(\"d1\", NodeKind.Delegation(\"worker\"), None, Vector.empty, nesting = 1, reason = \"recorded outcome: Cancelled\")\n" +
      "    }\n" +
