      "    }\n"

  // Id-level cycle: distinct node instances whose ids repeat an ancestor id
  // (the tree projection of a graph that was not acyclic).
  private def cyclicView(): LineageView =
    viewOf(
      "run-cycle",
      Vector(
        NodeView(
          "a",
          NodeKind.Phase("A"),
          None,
          Vector(
            NodeView(
              "b",
              NodeKind.Phase("B"),
              Some("a"),
              Vector(
                NodeView(
                  "a",
                  NodeKind.Phase("A-child"),
                  Some("b"),
                  Vector.empty,
                  None
                )
              ),
              None
            )
          ),
          None
        )
      )
    )

  // A kind this revision cannot render: the NodeKind enum is closed, so a
  // null kind stands in for a foreign kind a future wire revision (new enum
  // case, WIRE-FREEZE wave-3) could decode. Exercises the defensive
  // UnknownKind branch (LIN2-C-02): typed error, never a MatchError or NPE.
  // The defensive branch is deliberately tested via Option.empty[NodeKind]
  // .orNull (not the DisableSyntax.null literal): orNull yields the same
  // null kind the renderer would see from a foreign decode, while keeping
  // scalafix DisableSyntax.noNulls green.
  private def foreignView(): NodeView =
    NodeView("u1", Option.empty[NodeKind].orNull, None, Vector.empty, None)

  /** REN-01 (RAI-141): comment-only def bodies are a renderer bug after this
    * card. Every def/val body that opens with `=` must be followed by at least
    * one NON-comment statement at a deeper indent before the region closes; the
    * object body likewise. The renderer shape also never emits a standalone
    * `()` closer line anymore. Returns human-readable violations.
    */
  private def commentOnlyViolations(src: String): Vector[String] =
    val lines = src.linesIterator.toVector
    val problems = scala.collection.mutable.ArrayBuffer.empty[String]
    lines.zipWithIndex.foreach { (line, i) =>
      val t = line.trim
      val indent = line.takeWhile(_ == ' ').length
      if t == "()" then problems += "standalone `()` line at " + (i + 1)
      val opensBody =
        (t.startsWith("def ") || t.startsWith("val ")) && t.endsWith("=")
      val opensObject = t.startsWith("object ") && t.endsWith(":")
      if opensBody || opensObject then
        val next = lines.drop(i + 1).find(_.trim.nonEmpty)
        next match
          case None =>
            problems += "body opened at line " + (i + 1) + " has no statement"
          case Some(nl) =>
            val nIndent = nl.takeWhile(_ == ' ').length
            val commentOnly =
              nl.trim.startsWith("//") ||
                (nIndent <= indent && !opensObject) ||
                (opensObject && nIndent == 0)
            if commentOnly then
              problems += "body opened at line " + (i + 1) +
                " is comment-only or empty: next line: " + nl
      ()
    }
    problems.toVector

  def spec = suite("LineageProjection LIN-02 (RAI-141 executable composition)")(
    test("LIN2-C-01 golden tiny view renders byte-identical on repeat") {
      val first = LineageRenderer.render(tinyView)
      val second = LineageRenderer.render(tinyView)
      assertTrue(
        first == Right(golden),
        second == Right(golden),
        first.map(_.getBytes("UTF-8").toSeq) == Right(
          golden.getBytes("UTF-8").toSeq
        )
      )
    },
    test(
      "L34-01: deep chain renders flat object-level defs with real sub-Program bodies, byte-identical on repeat"
    ) {
      val first = LineageRenderer.render(deepChainView)
      val second = LineageRenderer.render(deepChainView)
      assertTrue(
        first == Right(deepChainGolden),
        second == Right(deepChainGolden),
        first.map(_.getBytes("UTF-8").toSeq) == Right(
          deepChainGolden.getBytes("UTF-8").toSeq
        )
      )
    },
    test(
      "LIN11-03: plain run renders a real object body (val program), byte-identical on repeat"
    ) {
      val first = LineageRenderer.render(plainRunView)
      val second = LineageRenderer.render(plainRunView)
      assertTrue(
        first == Right(plainRunGolden),
        second == Right(plainRunGolden),
        first.map(_.getBytes("UTF-8").toSeq) == Right(
          plainRunGolden.getBytes("UTF-8").toSeq
        )
      )
    },
    test(
      "LIN11-03: named def under an atomic root renders the mixed shape, byte-identical on repeat"
    ) {
      val first = LineageRenderer.render(nestedDefView)
      val second = LineageRenderer.render(nestedDefView)
      assertTrue(
        first == Right(nestedDefGolden),
        second == Right(nestedDefGolden),
        first.map(_.getBytes("UTF-8").toSeq) == Right(
          nestedDefGolden.getBytes("UTF-8").toSeq
        )
      )
    },
    test(
      "REN-01: every def/val body of every fixture render has at least one real statement (no comment-only bodies, no `()` closers)"
    ) {
      val renders = Vector(
        LineageRenderer.render(tinyView),
        LineageRenderer.render(deepChainView),
        LineageRenderer.render(plainRunView),
        LineageRenderer.render(nestedDefView),
        LineageRenderer.render(threadedView),
        LineageRenderer.render(failedView("Failed")),
        LineageRenderer.render(failedView("Cancelled")),
        LineageRenderer.render(failedView("Timeout")),
        LineageRenderer.render(failedView("Succeeded")),
        LineageRenderer.render(failedDefView)
      )
      val allRights = renders.forall(_.isRight)
      val violations = renders.collect { case Right(src) =>
        commentOnlyViolations(src)
      }.flatten
      val composed =
        renders
          .collect { case Right(src) => src }
          .forall(s =>
            s.contains("Program.fromFunction") && s.contains("LineageStep.")
          )
      assertTrue(
        allRights,
        violations.isEmpty,
        composed
      )
    },
    test(
      "RAI-141: in-scope dataflow dependency is threaded as a bound value (n_m1.head.id), byte-identical on repeat"
    ) {
      val first = LineageRenderer.render(threadedView)
      assertTrue(
        first == Right(threadedGolden),
        first.toOption.exists(_.contains("Vector(n_m1.head.id)"))
      )
    },
    test(
      "RAI-141: recorded Failed outcome projects to LineageStep.failed with the bounded reason phrase"
    ) {
      val rendered = LineageRenderer.render(failedView("Failed"))
      assertTrue(
        rendered == Right(failedGolden("Failed")),
        rendered.toOption.exists(src =>
          src.contains("LineageStep.failed(") &&
            src.contains("reason = \"recorded outcome: Failed\"") &&
            !src.contains("LineageStep.tool(")
        )
      )
    },
    test(
      "RAI-141: Cancelled and Timeout are recorded failures; Succeeded reports normally"
    ) {
      val cancelled = LineageRenderer.render(failedView("Cancelled"))
      val timeout = LineageRenderer.render(failedView("Timeout"))
      val succeeded = LineageRenderer.render(failedView("Succeeded"))
      assertTrue(
        cancelled == Right(failedGolden("Cancelled")),
        timeout == Right(failedGolden("Timeout")),
        succeeded.toOption.exists(src =>
          src.contains("LineageStep.tool(") && !src.contains(
            "LineageStep.failed"
          )
        )
      )
    },
    test(
      "RAI-141: a recorded failure on a named def's own node lives inside the sub-Program body"
    ) {
      val rendered = LineageRenderer.render(failedDefView)
      assertTrue(rendered == Right(failedDefGolden))
    },
    test(
      "RAI-141: unknown recorded outcome class → typed RenderError.UnknownKind, never guessed"
    ) {
      val view = viewOf(
        "run-bad-outcome",
        Vector(
          NodeView(
            "t1",
            NodeKind.ToolCall("edit_file", "Mutating"),
            None,
            Vector.empty,
            None,
            outcome = Some("Exploded")
          )
        )
      )
      val result = LineageRenderer.render(view)
      val unknown = result.left.toOption.exists {
        case RenderError.UnknownKind(detail) =>
          detail.contains("unsupported recorded outcome")
        case _ => false
      }
      assertTrue(unknown)
    },
    test("LIN2-C-02 foreign node kind → RenderError.UnknownKind") {
      val view = viewOf(
        "run-unknown",
        Vector(foreignView())
      )
      val result = LineageRenderer.render(view)
      val unknown = result.left.toOption.exists {
        case RenderError.UnknownKind(detail) => detail.nonEmpty
        case _                               => false
      }
      assertTrue(unknown)
    },
    test("empty graph → RenderError.Empty") {
      assertTrue(
        LineageRenderer.render(viewOf("run-empty", Vector.empty)) == Left(
          RenderError.Empty
        )
      )
    },
    test("id-level cycle → RenderError.Cyclic(repeated id)") {
      assertTrue(
        LineageRenderer.render(cyclicView()) == Left(RenderError.Cyclic("a"))
      )
    },
    test("duplicate def names are disambiguated deterministically") {
      val view = viewOf(
        "run-dup",
        Vector(
          NodeView("p1", NodeKind.Phase("verify"), None, Vector.empty, None),
          NodeView("p2", NodeKind.Phase("verify"), None, Vector.empty, None)
        )
      )
      val expected =
        prelude("lineage_run_dup") +
          "  val phase_verify: Program[Unit, Vector[StepReport]] =\n" +
          "    Program.fromFunction(\"phase_verify\") { _ =>\n" +
          "      LineageStep.phase(\"p1\", \"verify\", None, Vector.empty, nesting = 1)\n" +
          "    }\n" +
          "\n" +
          "  val phase_verify_2: Program[Unit, Vector[StepReport]] =\n" +
          "    Program.fromFunction(\"phase_verify_2\") { _ =>\n" +
          "      LineageStep.phase(\"p2\", \"verify\", None, Vector.empty, nesting = 1)\n" +
          "    }\n" +
          "\n" +
          "  val program: Program[Unit, Vector[StepReport]] =\n" +
          "    Program.fromFunction(\"lineage_run_dup\") { _ =>\n" +
          "      phase_verify(())\n" +
          "        .flatMap { n_p1 =>\n" +
          "          phase_verify_2(())\n" +
          "            .map { n_p2 =>\n" +
          "              n_p1 ++ n_p2\n" +
          "            }\n" +
          "        }\n" +
          "    }\n"
      assertTrue(LineageRenderer.render(view) == Right(expected))
    },
    test("LIN2-C-03 concurrent renders are identical and state-isolated") {
      val views = List.fill(8)(tinyView) ++ List.fill(8)(cyclicView())
      ZIO.foreachPar(views)(v => ZIO.succeed(LineageRenderer.render(v))).map {
        results =>
          val (rights, lefts) = results.partition(_.isRight)
          assertTrue(
            rights == List.fill(8)(Right(golden)),
            lefts == List.fill(8)(Left(RenderError.Cyclic("a")))
          )
      }
    },
    test(
      "W9F4-01: model/tool names with \n and \r keep every emitted line single-line"
    ) {
      // Pre-fix escape handled only `\` and `"`, so a raw newline inside a
      // model/tool/recovery name split the generated artifact into broken
      // lines. The fixed discipline neutralizes \n, \r, \t and other C0
      // controls exactly like the runtime GraphHash esc — now inside the
      // generated string literals too.
      val view = viewOf(
        "run-hostile",
        Vector(
          NodeView(
            "m1",
            NodeKind.ModelCall("gpt\n5\r-x\u0001", 1),
            None,
            Vector(
              NodeView(
                "t1",
                NodeKind.ToolCall("tool\tname\n2", "line\rbreak"),
                Some("m1"),
                Vector.empty,
                None
              )
            ),
            None
          )
        )
      )
      val expected =
        prelude("lineage_run_hostile") +
          "  val program: Program[Unit, Vector[StepReport]] =\n" +
          "    Program.fromFunction(\"lineage_run_hostile\") { _ =>\n" +
          "      LineageStep.model(\"m1\", \"gpt\\n5\\r-x\\x01\", 1, None, Vector.empty, nesting = 0)\n" +
          "        .flatMap { n_m1 =>\n" +
          "          LineageStep.tool(\"t1\", \"tool\\tname\\n2\", \"line\\rbreak\", None, Vector.empty, nesting = 0)\n" +
          "            .map { n_t1 =>\n" +
          "              n_m1 ++ n_t1\n" +
          "            }\n" +
          "        }\n" +
          "    }\n"
      val rendered = LineageRenderer.render(view)
      assertTrue(
        rendered == Right(expected),
        rendered.toOption.exists(out => out.linesIterator.length == 20)
      )
    },
    test("W9F4-01: data ref with \n stays on its comment line") {
      val view = viewOf(
        "run-ref",
        Vector(
          NodeView(
            "p1",
            NodeKind.Phase("verify"),
            None,
            Vector.empty,
            Some("d\nref")
          )
        )
      )
      val expected =
        prelude("lineage_run_ref") +
          "  val phase_verify: Program[Unit, Vector[StepReport]] =\n" +
          "    Program.fromFunction(\"phase_verify\") { _ =>\n" +
          "      LineageStep.phase(\"p1\", \"verify\", Some(\"d\\nref\"), Vector.empty, nesting = 1) // data: d\\nref\n" +
          "    }\n" +
          "\n" +
          "  val program: Program[Unit, Vector[StepReport]] =\n" +
          "    Program.fromFunction(\"lineage_run_ref\") { _ =>\n" +
          "      phase_verify(()) // data: d\\nref\n" +
          "    }\n"
      assertTrue(LineageRenderer.render(view) == Right(expected))
    }
  )
